{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Bicifadine, a small rigid bicyclic amine, has an absolute oral bioavailability of about 67% in humans, directly supporting that this chemotype can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Milnacipran, a cyclopropane-containing primary amine, has an absolute oral bioavailability of 85 ± 3% in humans, providing strong evidence that small polar/basic amines can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Mecamylamine, a rigid cage-like amine, has complete oral bioavailability in healthy subjects, closely paralleling the rigid adamantane-amine scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lamotrigine, an amino-substituted heteroaromatic, has 98% absolute oral bioavailability in humans, showing that basic amino-containing drugs can be almost completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Mirogabalin, a small primary amine with a carboxylic acid, has >85% oral bioavailability based on urinary excretion, supporting high F for small amino-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "PD 0200390, a cyclohexane primary amine/acid, shows high oral bioavailability with 85–97% urinary recovery of unchanged drug, reinforcing high absorption for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability for rigid, small, basic amine-containing molecules, with absolute F values ranging from 67% to 98% in humans. The query's adamantane primary amine is expected to be well absorbed and exceed 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule is provided.",
    "No human pharmacokinetic data for memantine itself are included in the evidence set.",
    "Potential first-pass metabolism or transporter-mediated efflux is not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

